const s = $('Write settings').first().json;
const p = $json;
const clean = t => String(t || '').replace(/[{}]/g, '').replace(/\s+/g, ' ').trim();
const options = p.hasOnlyDefaultVariant ? [] : p.options.filter(o => o.name !== 'Title');
const type = p.productType || 'default';
const variant = p.variants.nodes[0] || {};
const mpn = (p.mpn || variant.mpn || {}).value || '';

const lines = [
  'Current title: ' + clean(p.title),
  'Brand: ' + clean(p.vendor),
  'MPN: ' + clean(mpn || 'unknown'),
  'Type: ' + clean(type),
  'Description: ' + clean(p.description)
];
if (options.length) lines.push('Options: ' + options.map(o => o.name + ' (' + o.values.join(', ') + ')').join('; '));

return { json: {
  product_id: p.id, old_title: p.title, vendor: p.vendor, mpn, category: type,
  sku: variant.sku || '',
  description: clean(p.description),
  formula: s.formulas[type] || s.formulas.default,
  option_values: options.flatMap(o => o.values),
  image: p.featuredMedia && p.featuredMedia.preview ? p.featuredMedia.preview.image.url : '',
  input: lines.join('\n')
} };

const p = $('Build the input').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.title);
const same = rows.filter(r => r.category === p.category).slice(0, 5);
const extra = rows.filter(r => r.category !== p.category).slice(0, Math.max(0, 3 - same.length));
const examples = [...same, ...extra]
  .map(r => (r.input + '\nTitle: ' + r.title).replace(/[{}]/g, ''))
  .join('\n\n');
return [{ json: { ...p, examples } }];

