parameters.jsCode:
const s = $('Write settings').first().json;
const p = $('Build the input').first().json;
const reply = String($json.text || '');

const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const has = (text, word) => new RegExp('(^|[^A-Za-z0-9])' + esc(word) + '($|[^A-Za-z0-9])', 'i').test(text);
const inches = t => String(t).replace(/(\d)\s*(?:"|inch(?:es)?\b)/gi, '$1in');
const tidy = t => String(t || '').replace(/\s*[\u2013\u2014]\s*/g, ', ').replace(/["\u201C\u201D]/g, '').replace(/\s+/g, ' ').trim();

let title = tidy(inches((reply.match(/^\s*\**title\**\s*:\s*(.+)$/im) || [])[1] || ''));
const source = inches([p.old_title, p.vendor, p.mpn, p.sku, p.description].join(' '));

// Whole tokens from the source, plus the pieces of each one split on / - ( )
const sourceTokens = new Set();
for (const w of source.toUpperCase().split(/\s+/)) {
  const t = w.replace(/^[^A-Z0-9]+|[^A-Z0-9+]+$/g, '');
  if (!t) continue;
  sourceTokens.add(t);
  t.split(/[\/()\-]/).filter(Boolean).forEach(x => sourceTokens.add(x));
}

const problems = [];
if (!title) problems.push('no title in the reply');

// 1. Any code with letters and digits must be a whole token from the source
for (const w of title.split(' ')) {
  const t = w.toUpperCase().replace(/^[^A-Z0-9]+|[^A-Z0-9+]+$/g, '');
  if (/[A-Z]/.test(t) && /\d/.test(t) && !sourceTokens.has(t)) problems.push('code not in source: ' + w);
}

// 2. Every number must appear in the source
const nums = t => t.match(/\d+(?:\.\d+)?/g) || [];
const sourceNums = new Set(nums(source));
for (const n of nums(title)) if (!sourceNums.has(n)) problems.push('number not in source: ' + n);

// 3. Variants: no option values on a multi-variant product, its own colour on a single one
if (p.option_values.length) {
  for (const v of p.option_values) if (has(title, v)) problems.push('names one option: ' + v);
} else {
  const colour = s.colour_words.find(c => has(p.old_title, c));
  if (colour && title && !has(title, colour)) {
    const at = p.mpn ? title.toUpperCase().indexOf(p.mpn.toUpperCase()) : -1;
    title = at >= 0
      ? title.slice(0, at + p.mpn.length) + ' ' + colour + title.slice(at + p.mpn.length)
      : title + ' ' + colour;
  }
}

// 4. Length and banned words
if (title.length > s.max_length) problems.push('too long (' + title.length + ')');
for (const b of s.banned_words) if (has(title, b)) problems.push('banned word: ' + b);

// 5. A failed title falls back to the current one, tidied
const fallback = () => {
  let t = tidy(p.old_title).replace(/,?\s*\b\d+\s*(?:years?|yrs?|y)\b(?:\s+warranty)?/gi, '').replace(/\s+/g, ' ').trim();
  if (t === t.toUpperCase()) t = t.split(' ').map(w => /\d/.test(w) || w.length <= 3 ? w : w[0] + w.slice(1).toLowerCase()).join(' ');
  // the brand as the brand writes it
  if (p.vendor && t.toUpperCase().startsWith(p.vendor.toUpperCase())) t = p.vendor + t.slice(p.vendor.length);
  else if (p.vendor) t = p.vendor + ' ' + t;
  if (t.length > s.max_length) t = t.slice(0, s.max_length + 1).replace(/\s+\S*$/, '');
  return t.replace(/[\s,;:\/-]+$/, '');
};

const failed = problems.length > 0;
return { json: { ...p,
  new_title: failed ? fallback() : title,
  model_title: title,
  title_source: failed ? 'fallback' : 'ai',
  problems: problems.join('; ')
} };

