={{ (() => {
  const t = $('When Executed by Another Workflow').first().json;
  const state = $('Mark approved').isExecuted ? 'approved' : $('Mark stale').isExecuted ? 'stale' : 'error';
  const head = { approved: 'Title approved', stale: 'Title not changed', error: 'Title not saved' }[state];
  let note;
  if (state === 'approved') note = ':white_check_mark: ' + (t.source === 'edited' ? 'Edited and approved' : 'Approved') + ' by @' + t.user + '. Shopify updated.';
  else if (state === 'stale') note = ':warning: Someone changed the title in Shopify since this draft, so it was left alone. It is now: ' + $('Read the live title').first().json.data.product.title;
  else { const r = $('Update the title').first().json;
    note = ':x: Shopify refused it: ' + [...(r.errors || []), ...(r.data?.productUpdate?.userErrors || [])].map(e => e.message).join('; '); }
  return JSON.stringify({ blocks: [
    { type: 'header', text: { type: 'plain_text', text: '' + head } },
    { type: 'section', text: { type: 'mrkdwn', text: '*Before*\n' + t.old_title + '\n*After*\n' + t.title } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: note }] },
    ...(state === 'error' ? [{ type: 'actions', elements: [
      { type: 'button', style: 'primary', text: { type: 'plain_text', text: 'Approve' }, action_id: 'title_approve', value: t.product_id },
      { type: 'button', text: { type: 'plain_text', text: 'Edit' }, action_id: 'title_edit', value: t.product_id },
      { type: 'button', style: 'danger', text: { type: 'plain_text', text: 'Reject' }, action_id: 'title_reject', value: t.product_id }
    ] }] : [])
  ] });
})() }}
